r_favorite_seller(uuid, uuid, double precision, double precision, double precision)', 'public.log_admin_analytics_event(text, text, text, jsonb, jsonb)', 'public.log_interaction_event(uuid, uuid, uuid, text, double precision, double precision, jsonb)', 'public.moderar_producto(uuid, numeric, integer, text)', 'public.ocultar_alerta_dashboard(uuid)', 'public.ocultar_ruta(text)', 'public.product_search_audit(integer, integer)', 'public.radar_mvt(integer, integer, integer)', 'public.reactivar_vendedor(uuid, text, boolean)', 'public.refresh_mv_admin_heatmap_supply()', 'public.registrar_accion_admin(uuid, text, text)', 'public.reportes_moderacion()', 'public.reputacion_dashboard(uuid)', 'public.resolve_admin_alert(uuid, uuid, character varying, text)', 'public.restaurar_producto(uuid, text)', 'public.restaurar_ruta(text)', 'public.revertir_cambio_vendedor(uuid)', 'public.rpc_riesgo_traza_dashboard()', 'public.rpc_v4_seller_accept_order(uuid, integer)', 'public.safe_hide_alert(uuid, text)', 'public.sessions_tokens()', 'public.sincronizar_grafo_comercial()', 'public.sincronizar_grafo_ordenes()', 'public.sync_order_completion_to_graph(uuid)', 'public.sync_purchase_to_graph(uuid)', 'public.sync_reputacion_score_desde_age(uuid)', 'public.tg_admin_moderacion_audit_age()', 'public.tg_archivar_reporte()', 'public.tg_audit_api_doc_age()', 'public.tg_audit_config_seguridad()', 'public.tg_disparar_alerta_riesgo_age()', 'public.tg_prevent_delete_h_doc_audit()', 'public.tg_soft_hide_alerta()', 'public.user_role_change_audit(uuid, integer, integer)', 'public.validar_coordenadas_comprador(double precision, double precision, double precision, text)', 'public.validate_corporate_email(character varying)', 'public.validate_password_strength(character varying)']::regprocedure[]) ORDER BY 2 LOOP
    IF EXISTS (SELECT 1 FROM pg_stat_user_functions s WHERE s.funcid = r.oid AND s.calls > 0) THEN
      INSERT INTO traza.sanidad_bitacora(paquete, accion, objeto) VALUES ('S05', 'en_uso', r.rp); CONTINUE;
    END IF;
    IF r.lanname <> 'plpgsql' AND v_track <> 'all' THEN
      INSERT INTO traza.sanidad_bitacora(paquete, accion, objeto) VALUES ('S05', 'sin_medicion_sql', r.rp); CONTINUE;
    END IF;
    v_en_cron := false;
    IF v_cron THEN EXECUTE 'SELECT EXISTS (SELECT 1 FROM cron.job WHERE command ~* $1)' INTO v_en_cron USING '\m' || r.proname || '\M'; END IF;
    IF v_en_cron THEN INSERT INTO traza.sanidad_bitacora(paquete, accion, objeto) VALUES ('S05', 'en_cron', r.rp); CONTINUE; END IF;
    v_rev := '{}';
    FOR g IN SELECT DISTINCT CASE WHEN x.grantee = 0 THEN 'PUBLIC' ELSE quote_ident(x.grantee::regrole::text) END
             FROM aclexplode(r.acl) x LEFT JOIN pg_roles ro ON ro.oid = x.grantee
             WHERE x.privilege_type = 'EXECUTE' AND x.grantee <> r.proowner AND NOT coalesce(ro.rolsuper, false) LOOP
      EXECUTE format('REVOKE EXECUTE ON FUNCTION %s FROM %s', r.rp, g); v_rev := v_rev || g;
    END LOOP;
    INSERT INTO traza.sanidad_bitacora(paquete, accion, objeto, detalle) VALUES ('S05', 'retiro_suave', r.rp, jsonb_build_object('revocados', v_rev, 'acl_previa', r.acl::text));
  END LOOP;
END $s05$;

DO $s06$
DECLARE
  v_dias int := coalesce(nullif(current_setting('traza.dias_minimos', true), ''), '30')::int; v_reset timestamptz; r record; g text; v_rev text[];
BEGIN
  SELECT stats_reset INTO v_reset FROM pg_stat_database WHERE datname = current_database();
  IF v_reset IS NULL OR v_reset > now() - make_interval(days => v_dias) THEN
    RAISE NOTICE 'traza S06: sin ventana de evidencia (stats_reset=%); no se retira nada', v_reset;
    INSERT INTO traza.sanidad_bitacora(paquete, accion, objeto, detalle) VALUES ('S06', 'sin_evidencia', current_database(), jsonb_build_object('stats_reset', v_reset));
    RETURN;
  END IF;
  FOR r IN SELECT c.oid, c.oid::regclass::text AS rel, c.relowner, coalesce(c.relacl, acldefault('r', c.relowner)) AS acl,
                  coalesce(s.seq_scan, 0) + coalesce(s.idx_scan, 0) + coalesce(s.n_tup_ins, 0) + coalesce(s.n_tup_upd, 0) + coalesce(s.n_tup_del, 0) AS uso
           FROM pg_class c LEFT JOIN pg_stat_user_tables s ON s.relid = c.oid
           WHERE c.oid = ANY (ARRAY['admin.admin_approvals', 'admin.admin_permissions', 'admin.admin_roles', 'admin.administrators', 'analytics.cohortes_clientes', 'analytics.exportaciones_reportes', 'analytics.informes_admin', 'analytics.log_control_etl', 'analytics.log_errores_etl', 'analytics.metricas_kpi', 'analytics.pronostico_demanda', 'analytics.valores_metricas', 'analytics.viaje_cliente', 'analytics.widgets_panel', 'app.billeteras', 'audit.admin_sessions', 'audit.anomaly_detection', 'audit.ledger', 'audit.session_logs', 'auth.age_sync_failures', 'auth.auditoria_camino_mas_corto', 'auth.auditoria_comunidades', 'auth.buyer_clv_scores', 'auth.cat_tipos_producto', 'auth.colonias_xalapa', 'auth.merca_daily_snapshot', 'auth.metricas', 'disputes.dispute_appeals', 'disputes.dispute_messages', 'fraud.fraud_detection_logs', 'fraud.fraud_rules', 'kambalache_cu.idx_cu_dependencies', 'moderation.content_audit_trail', 'moderation.content_reviews', 'moderation.moderation_appeals', 'moderation.moderation_rules', 'public.admin_alertas_consola_listar', 'public.auditoria', 'public.buscar_vendedores_cercanos', 'public.e2e_trazas', 'public.historial_intercambios', 'public.imagenes_articulo', 'public.negociaciones', 'public.promociones', 'public.promociones_aplicadas', 'public.schema_version']::regclass[]) ORDER BY 2 LOOP
    IF r.uso > 0 THEN INSERT INTO traza.sanidad_bitacora(paquete, accion, objeto, detalle) VALUES ('S06', 'en_uso', r.rel, jsonb_build_object('uso', r.uso)); CONTINUE; END IF;
    v_rev := '{}';
    FOR g IN SELECT DISTINCT CASE WHEN x.grantee = 0 THEN 'PUBLIC' ELSE quote_ident(x.grantee::regrole::text) END
             FROM aclexplode(r.acl) x LEFT JOIN pg_roles ro ON ro.oid = x.grantee
             WHERE x.grantee <> r.relowner AND NOT coalesce(ro.rolsuper, false) LOOP
      EXECUTE format('REVOKE ALL ON TABLE %s FROM %s', r.rel, g); v_rev := v_rev || g;
    END LOOP;
    INSERT INTO traza.sanidad_bitacora(paquete, accion, objeto, detalle) VALUES ('S06', 'retiro_suave', r.rel, jsonb_build_object('revocados', v_rev, 'acl_previa', r.acl::text));
  END LOOP;
END $s06$;

COMMIT;
